UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 50, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 51, 7, NULL::text),(3, 179, 28, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 211, 1050, NULL::text),(6,0,0,E'd) Las pastas de balata adheridas deben tener un grosor igual o mayor a 3.2 mm (1/8"). Las pastas de balata remachadas deben tener un grosor igual o mayor a 4.8 mm (3/16"), o en su caso, la superficie debe encontrarse distante a las dimensiones especificadas por el fabricante del vehículo y en ningún caso la medida debe ser inferior a 1.6 mm (1/16") por encima de la cabeza del remache. Las pastas de balata deben estar exentas de evidencia de contaminación que afecte el desempeño de frenado y los sellos de las ruedas no deben mostrar evidencia de fugas. Las pastas deben estar presentes y ajustadas en la balata y no estar rotas.'),(7, 1910, 401, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='53ce6ac3-fa4d-5a33-94a0-de3b575a80d8' AND md5(a.contenido)='295c8b3cb898f790d72a9b71a746b3de' RETURNING a.id,md5(a.contenido) hash;